import{_ as t,c as e,o as l,a5 as i}from"./chunks/framework.BmNIwhaK.js";const m=JSON.parse('{"title":"ストーリーポイント","description":"ストーリーポイントは、作業の規模、複雑性、不確実性を相対的に見積もる単位です。絶対的な時間と直接対応させるのではなく、スプリント単位での合理的な作業量の把握とチームスケジュールの見積りを目的としています。","frontmatter":{"title":"ストーリーポイント","description":"ストーリーポイントは、作業の規模、複雑性、不確実性を相対的に見積もる単位です。絶対的な時間と直接対応させるのではなく、スプリント単位での合理的な作業量の把握とチームスケジュールの見積りを目的としています。","head":[["meta",{"name":"keywords","content":"スクランバン, Scrumban, スクランバン紹介, スクランバン概要, スクランバンとは, Scrumban紹介, Scrumban概要, スクラムとカンバンの違い, スクラム vs カンバン, アジャイル手法, アジャイルフレームワーク, カンバン手法, スクラム手法, スクランバンプロセス, スクランバン運用ガイド, スクランバンボード, WIP制限, ワークフロー管理, カンバンボードの使い方, スクランバンのメリット, スクランバンの特徴, スクランバンの効果, スクランバン活用事例, スクランバン導入効果, スクランバン Jira設定, スクランバンボードテンプレート, Scrumbanツール, スクランバンコラボレーションツール, スクランバンワークフロー, アジャイルプロジェクト管理, 業務効率化手法, 反復的タスク管理, ボトルネック解消"}],["meta",{"property":"og:title","content":"スクランバン"}],["meta",{"property":"og:description","content":"スクランバン（Scrumban）は、スクラムの反復的な構造とカンバンのフロー管理・WIP制限を組み合わせ、柔軟かつ効率的に作業を管理するハイブリッド型アジャイル手法です。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/storyPointGuide"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/agile/storyPointGuide"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/agile/storyPointGuide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"ストーリーポイント | Empasy Docs"}],["meta",{"property":"og:description","content":"ストーリーポイントは、作業の規模、複雑性、不確実性を相対的に見積もる単位です。絶対的な時間と直接対応させるのではなく、スプリント単位での合理的な作業量の把握とチームスケジュールの見積りを目的としています。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/agile/storyPointGuide"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"ストーリーポイント | Empasy Docs"}],["meta",{"name":"twitter:description","content":"ストーリーポイントは、作業の規模、複雑性、不確実性を相対的に見積もる単位です。絶対的な時間と直接対応させるのではなく、スプリント単位での合理的な作業量の把握とチームスケジュールの見積りを目的としています。"}]],"sort":2000},"headers":[],"relativePath":"ja/agile/storyPointGuide.md","filePath":"ja/agile/storyPointGuide.md","lastUpdated":1795293539000}'),r={name:"ja/agile/storyPointGuide.md"};function o(n,a,d,h,s,c){return l(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="ストーリーポイントガイド-アジャイルチームのための作業見積り手法" tabindex="-1">ストーリーポイントガイド：アジャイルチームのための作業見積り手法 <a class="header-anchor" href="#ストーリーポイントガイド-アジャイルチームのための作業見積り手法" aria-label="Permalink to “ストーリーポイントガイド：アジャイルチームのための作業見積り手法”">​</a></h1><h2 id="ストーリーポイントとは" tabindex="-1">ストーリーポイントとは？ <a class="header-anchor" href="#ストーリーポイントとは" aria-label="Permalink to “ストーリーポイントとは？”">​</a></h2><p>ストーリーポイントは、作業の <strong>規模、複雑性、不確実性</strong> を相対的に見積もる単位です。絶対的な時間と直接対応させるのではなく、スプリント単位での合理的な作業量の把握とチームスケジュールの見積りを目的としています。</p><blockquote><p>「5ポイント ＝ 1ポイントの5倍の時間」という考え方は誤りです</p></blockquote><h2 id="フィボナッチ数列を使用する理由" tabindex="-1">フィボナッチ数列を使用する理由 <a class="header-anchor" href="#フィボナッチ数列を使用する理由" aria-label="Permalink to “フィボナッチ数列を使用する理由”">​</a></h2><p>ストーリーポイントの見積りには、一般的に <strong>1, 2, 3, 5, 8, 13, 21...</strong> のようなフィボナッチ数列を使用します。このように連続した数値ではなく数列を使用する理由は次のとおりです。</p><ul><li>差が次第に大きくなり、不確実性を反映します</li><li>5と6の差よりも、5と8の差のほうが明確です</li><li>大きな作業になるほど複雑性とリスクが指数関数的に増加することを反映します</li><li>結果としてチームの合意形成が容易になり、過大／過小見積りを減らすことができます</li></ul><h2 id="ストーリーポイントの活用例" tabindex="-1">ストーリーポイントの活用例 <a class="header-anchor" href="#ストーリーポイントの活用例" aria-label="Permalink to “ストーリーポイントの活用例”">​</a></h2><table tabindex="0"><thead><tr><th>作業項目</th><th>ポイント</th><th>説明</th></tr></thead><tbody><tr><td>ユーザー調査</td><td>3ポイント</td><td>比較的軽い労力で済む作業</td></tr><tr><td>ワイヤーフレーム</td><td>5ポイント</td><td>ユーザー調査後に進めるシンプルな作業</td></tr><tr><td>UIデザイン</td><td>8ポイント</td><td>チーム内での調整が必要な作業</td></tr><tr><td>開発作業</td><td>13ポイント</td><td>多くの要素が関与し複雑な作業</td></tr><tr><td>QAテスト</td><td>8ポイント</td><td>複雑ではあるが管理可能なレベルの作業</td></tr></tbody></table><h2 id="基準タスクの例" tabindex="-1">基準タスクの例 <a class="header-anchor" href="#基準タスクの例" aria-label="Permalink to “基準タスクの例”">​</a></h2><h3 id="ストーリーポイント-5-ユーザーパスワードリセット機能" tabindex="-1">ストーリーポイント 5：ユーザーパスワードリセット機能 <a class="header-anchor" href="#ストーリーポイント-5-ユーザーパスワードリセット機能" aria-label="Permalink to “ストーリーポイント 5：ユーザーパスワードリセット機能”">​</a></h3><p><strong>Doneの定義</strong></p><ul><li>パスワード変更機能の実装</li><li>メール認証機能の実装</li><li>パスワードルールの遵守（英字＋数字など）</li></ul><p><strong>補足考慮事項</strong></p><ul><li>DBテーブル設計</li><li>メール送受信環境</li><li>例外事項は考慮しなくてよい</li></ul><h3 id="ストーリーポイント-13-クレジットカード決済機能" tabindex="-1">ストーリーポイント 13：クレジットカード決済機能 <a class="header-anchor" href="#ストーリーポイント-13-クレジットカード決済機能" aria-label="Permalink to “ストーリーポイント 13：クレジットカード決済機能”">​</a></h3><p><strong>Doneの定義</strong></p><ul><li>商品決済機能の実装</li><li>Myページでの購入履歴照会が可能</li><li>管理者も確認可能</li></ul><p><strong>補足考慮事項</strong></p><ul><li>カード登録機能は既存のものがある</li><li>DB設計が必要</li><li>エラーパターンは考慮しなくてよい</li></ul><h2 id="注意事項-誤った使い方" tabindex="-1">注意事項：誤った使い方 <a class="header-anchor" href="#注意事項-誤った使い方" aria-label="Permalink to “注意事項：誤った使い方”">​</a></h2><p><strong>時間をそのまま当てはめる方式は避けるべきです</strong></p><ul><li>「4時間の業務 ＝ 1ポイント」 → 従来の方式と変わりません</li><li>「5ポイント ＝ 1ポイントの5倍の時間」</li></ul><p><strong>正しい意味</strong>: 1ポイントよりも5倍複雑であるという意味です。このような誤ったアプローチは、ストーリーポイントの本質を損ないます。</p><h2 id="リファクタリングと品質に関する考慮事項" tabindex="-1">リファクタリングと品質に関する考慮事項 <a class="header-anchor" href="#リファクタリングと品質に関する考慮事項" aria-label="Permalink to “リファクタリングと品質に関する考慮事項”">​</a></h2><p>すべてのストーリーには、次の2つの要素が必ず含まれなければなりません。</p><ol><li><strong>期待どおりに動く</strong>機能</li><li><strong>正しく作られている</strong>品質</li></ol><p>1つ目の要素だけを満たし2つ目の要素を無視すると、ストーリーポイントは不完全になります。リファクタリング作業も、品質向上（技術的負債の解消）の観点からポイントを付与することができます。</p><blockquote><p>注意：ストーリーポイントは個人のパフォーマンス比較用としては絶対に使用しないでください。これは純粋にチーム単位のツールです。</p></blockquote><h2 id="要点まとめ" tabindex="-1">要点まとめ <a class="header-anchor" href="#要点まとめ" aria-label="Permalink to “要点まとめ”">​</a></h2><ul><li>ストーリーポイントは <strong>相対的な見積り単位</strong> です</li><li>時間換算ではなく、作業の <strong>複雑性／不確実性の比較</strong> が目的です</li><li>フィボナッチ数列を使用し、大きな作業ほどリスクが大きくなる点を反映します</li><li>チーム合意の基準（3、5、8、13など）を決めておき、新しい作業を比較して決定します</li><li>誤った時間対応方式は避け、品質基準を必ず反映します</li></ul><hr><h1 id="ストーリーポイント会議の進行ガイド" tabindex="-1">ストーリーポイント会議の進行ガイド <a class="header-anchor" href="#ストーリーポイント会議の進行ガイド" aria-label="Permalink to “ストーリーポイント会議の進行ガイド”">​</a></h1><h2 id="会議アジェンダ" tabindex="-1">会議アジェンダ <a class="header-anchor" href="#会議アジェンダ" aria-label="Permalink to “会議アジェンダ”">​</a></h2><h3 id="オープニング-5分" tabindex="-1">オープニング（5分） <a class="header-anchor" href="#オープニング-5分" aria-label="Permalink to “オープニング（5分）”">​</a></h3><ul><li>会議の目的説明：今スプリントの作業難易度／複雑性を相対的に見積もること</li><li>絶対的な時間単位ではなく、相対的な規模の比較を通じて合意することを強調</li></ul><h3 id="基本概念のリマインド-10分" tabindex="-1">基本概念のリマインド（10分） <a class="header-anchor" href="#基本概念のリマインド-10分" aria-label="Permalink to “基本概念のリマインド（10分）”">​</a></h3><ul><li>ストーリーポイントの定義：作業の規模、複雑性、不確実性を表す単位</li><li>時間と1対1で対応させない（「5ポイント ＝ 1ポイントの5倍の時間」）</li><li>フィボナッチ数列を使用する理由の説明（1, 2, 3, 5, 8, 13, 21...）</li></ul><h3 id="基準事例の共有-10分" tabindex="-1">基準事例の共有（10分） <a class="header-anchor" href="#基準事例の共有-10分" aria-label="Permalink to “基準事例の共有（10分）”">​</a></h3><ul><li>ストーリーポイントの例の共有（ユーザー調査 → 3、ワイヤーフレーム → 5 など）</li><li>具体的な基準タスクの検討（5ポイント：パスワードリセット、13ポイント：クレジットカード決済）</li></ul><h3 id="誤った使い方の注意-5分" tabindex="-1">誤った使い方の注意（5分） <a class="header-anchor" href="#誤った使い方の注意-5分" aria-label="Permalink to “誤った使い方の注意（5分）”">​</a></h3><ul><li>時間をそのまま当てはめないことを強調</li><li>「5ポイント ＝ 1ポイントの5倍の時間」</li><li>正しい解釈：「1ポイントより5倍複雑である」</li></ul><h3 id="リファクタリングおよび品質の考慮-10分" tabindex="-1">リファクタリングおよび品質の考慮（10分） <a class="header-anchor" href="#リファクタリングおよび品質の考慮-10分" aria-label="Permalink to “リファクタリングおよび品質の考慮（10分）”">​</a></h3><ul><li>すべてのストーリーには [1] 期待どおりに動くこと ＋ [2] 正しく作られていること（品質）を含める必要がある</li><li>リファクタリング／技術的負債の改善も状況に応じてポイント設定が必要</li><li>個人のパフォーマンス比較用ではないことを再強調</li></ul><h3 id="実際の作業見積り-30〜40分" tabindex="-1">実際の作業見積り（30〜40分） <a class="header-anchor" href="#実際の作業見積り-30〜40分" aria-label="Permalink to “実際の作業見積り（30〜40分）”">​</a></h3><ul><li>バックログアイテムを1つずつ確認</li><li>基準事例と比較して議論</li><li>チーム合意 → フィボナッチ数のいずれかで決定（例：3、5、8、13）</li><li>課題や意見の衝突がある場合は合意点を見出す</li></ul><h3 id="クロージング-5分" tabindex="-1">クロージング（5分） <a class="header-anchor" href="#クロージング-5分" aria-label="Permalink to “クロージング（5分）”">​</a></h3><ul><li>会議で決定したストーリーポイントの結果を整理</li><li>次回スプリント計画時に反映予定であることを周知</li><li>「ストーリーポイントは、チームがスケジュールを迅速かつ容易に見積もれるよう支援するツール」であることを再強調</li></ul><p>ストーリーポイントはチームの生産性とスケジュール管理に有用なツールですが、正しく理解して使用するときにこそ真の価値を発揮します。</p>',49)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
